  if (tipo === "orden") return { proyecto: "", centroCosto: "", objetivo: "", visitaTecnica: "", cliente: "", fechaInicio: "", fechaFin: "", responsable: "", autoriza: "", tipos: [], otroTipo: "", actividades: emptyRows(3, () => ({ id: uid(), descripcion: "", unidad: "UND", cantidad: "", ejecutada: "", adicional: "", aprobacion: "", observaciones: "" })), riesgosCalidad: "", requisitos: REQUISITOS_LUGAR.map((x) => ({ id: uid(), nombre: x, cumple: "", observaciones: "" })), peligros: PELIGROS.map(([categoria, nombre]) => ({ id: uid(), categoria, nombre, presente: "", observaciones: "" })), aspectos: ASPECTOS.map((nombre) => ({ id: uid(), nombre, aplica: "", observaciones: "" })), observacionesSst: "", firmaResponsable: "", firmaRecibe: "" };
  if (tipo === "liquidacion") return { proceso: "", objeto: "", contratoNo: "", actaNo: "", interventoria: "", valorInicial: "", tipoObra: "", fechaInicio: "", fechaTerminacion: "", fechaActa: today(), valorAdicional: "", anticipoPct: "", valorAcumuladoAnterior: "", fechaAnticipo: "", concesion: "", proyecto: "", visitaTecnica: "", ubicacion: "", presupuestoNo: "", lineas: emptyRows(3, () => ({ id: uid(), codigo: "", descripcion: "", unidad: "UND", cantidadInicial: "", valorUnitario: "", cantidadPresente: "", cantidadAcumulada: "" })), incrementoInicial: "", incrementoPresente: "", incrementoAcumulado: "", aiuInicial: "", aiuPresente: "", aiuAcumulado: "", valorLetras: "", repEi: "", repInterventoria: "" };
