function completion(tipo, d) {
  let values = [];
  if (tipo === "bitacora") values = [d.fecha, d.proyecto, d.cuadrilla, d.novedades, d.procedimiento, d.pendientes];
  if (tipo === "control-material") values = [d.proyecto, d.fechaInicio, d.destino, d.sucursal];
  if (tipo === "solicitud-materiales") values = [d.fecha, d.proyecto, d.responsable];
  if (tipo === "finalizacion") values = [d.fechaActa, d.ciudad, d.codigoProyecto, d.objeto, d.contratista, d.nit, d.contratoNo, d.fechaContrato, d.valorContrato, d.fechaFinalizacion, d.valorFinal, d.repContratista, d.contratante, d.repContratante1, d.interventor, d.recibo, d.cumple];
  if (tipo === "herramienta") values = d.modalidad === "H2" ? [d.modalidad] : [d.modalidad, d.nombre, d.descripcion, d.marca, d.referencia, d.serial, d.fechaAdquisicion];
  if (tipo === "orden") values = [d.proyecto, d.centroCosto, d.objetivo, d.cliente, d.fechaInicio, d.fechaFin, d.responsable, d.autoriza];
  if (tipo === "liquidacion") values = [d.proceso, d.objeto, d.contratoNo, d.actaNo, d.interventoria, d.valorInicial, d.tipoObra, d.fechaInicio, d.fechaTerminacion, d.fechaActa, d.proyecto, d.presupuestoNo];
  return values.length ? values.filter((v) => String(v ?? "").trim()).length / values.length : 0;
}

function validate(tipo, d) {
  const a = [];
  const req = (v, txt) => { if (!String(v ?? "").trim()) a.push(txt); };
  if (tipo === "bitacora") {
    [[d.fecha,"Defina la fecha"],[d.proyecto,"Defina el proyecto"],[d.cuadrilla,"Registre la cuadrilla"],[d.novedades,"Registre novedades o “Sin novedades”"],[d.procedimiento,"Describa el procedimiento ejecutado"],[d.pendientes,"Registre pendientes o “Sin pendientes”"]].forEach(([v,t])=>req(v,t));
    (d.cantidades || []).filter(x => x.descripcion || num(x.cantidad)).forEach((x,i) => { if (!x.descripcion) a.push(`Cantidad ${i+1}: falta descripción`); if (num(x.cantidad) && !x.unidad) a.push(`Cantidad ${i+1}: falta U/M`); });
  }
  if (tipo === "control-material") {
    [[d.proyecto,"Defina el proyecto"],[d.fechaInicio,"Defina la fecha de inicio"],[d.destino,"Defina el destino"],[d.sucursal,"Defina la sucursal"]].forEach(([v,t])=>req(v,t));
    (d.lineas || []).filter(x=>x.descripcion).forEach((x,i)=>{ const q=num(x.cantidad),u=num(x.utilizado),dv=num(x.devuelto); if(q<=0)a.push(`Material ${i+1}: cantidad debe ser mayor a cero`); if(u+dv>q)a.push(`Material ${i+1}: utilizado + devuelto supera lo requerido`); if(dv>0&&!x.fechaDev)a.push(`Material ${i+1}: falta fecha de devolución`); if(x.fechaEnt&&(!x.entregadoPor||!x.recibidoPor))a.push(`Material ${i+1}: complete responsables de entrega/recibo`); if(x.fechaReq&&x.fechaEnt&&x.fechaEnt<x.fechaReq)a.push(`Material ${i+1}: entrega anterior al requerimiento`); });
  }
  if (tipo === "solicitud-materiales") {
    [[d.fecha,"Defina la fecha"],[d.proyecto,"Defina el proyecto"],[d.responsable,"Defina el responsable"]].forEach(([v,t])=>req(v,t));
    (d.lineas || []).filter(x=>x.descripcion).forEach((x,i)=>{ const s=num(x.solicitada),f=num(x.facturada),u=num(x.utilizada),dv=num(x.devuelta); if(s<=0)a.push(`Material ${i+1}: cantidad solicitada inválida`); if(f>0&&!x.factura)a.push(`Material ${i+1}: registre No. factura`); if(dv>0&&!x.devolucion)a.push(`Material ${i+1}: registre No. devolución`); if(u+dv>s)a.push(`Material ${i+1}: utilizado + devuelto supera lo solicitado`); });
  }
  if (tipo === "finalizacion") {
    [[d.fechaActa,"Fecha del acta"],[d.ciudad,"Ciudad"],[d.codigoProyecto,"Código / proyecto"],[d.objeto,"Obra / objeto contractual"],[d.contratista,"Contratista"],[d.nit,"NIT"],[d.contratoNo,"Contrato No."],[d.fechaContrato,"Fecha del contrato"],[d.valorContrato,"Valor del contrato"],[d.fechaFinalizacion,"Fecha de finalización"],[d.valorFinal,"Valor final"],[d.repContratista,"Representante contratista"],[d.contratante,"Contratante"],[d.repContratante1,"Representante contratante"],[d.interventor,"Interventor"],[d.recibo,"Recibo a satisfacción"],[d.cumple,"Cumplimiento técnico"]].forEach(([v,n])=>req(v,`Complete ${n}`));
    if (d.fechaActa && d.fechaFinalizacion && d.fechaActa < d.fechaFinalizacion) a.push("La fecha del acta no puede ser anterior a la finalización");
    if (d.recibo && d.recibo !== "Sí") a.push("El recibo a satisfacción requiere revisión");
    if (d.cumple && d.cumple !== "Sí") a.push("El cumplimiento técnico requiere revisión");
    if (d.pendientesAbiertos === "Sí" && !d.observaciones) a.push("Describa los pendientes abiertos");
  }
  if (tipo === "herramienta") {
    if (d.modalidad !== "H2") [[d.nombre,"Nombre"],[d.descripcion,"Descripción"],[d.marca,"Marca"],[d.referencia,"Referencia"],[d.serial,"No. de serie"],[d.fechaAdquisicion,"Fecha de adquisición"]].forEach(([v,n])=>req(v,`Complete ${n}`));
    if (d.modalidad === "AP" && d.entrega?.fecha && (!d.entrega.entrega || !d.entrega.recibe)) a.push("Complete responsables de la entrega AP");
    if (d.modalidad === "H2") (d.movimientos||[]).forEach((m,i)=>{ const tools=(m.herramientas||[]).filter(x=>x.nombre); if(m.entrega?.fecha && !tools.length)a.push(`Movimiento ${i+1}: agregue al menos una herramienta`); if(m.entrega?.fecha&&(!m.entrega.entrega||!m.entrega.recibe))a.push(`Movimiento ${i+1}: complete responsables de entrega`); if(m.devolucion?.fecha&&(!m.devolucion.entrega||!m.devolucion.recibe))a.push(`Movimiento ${i+1}: complete responsables de devolución`); });
    (d.mantenimientos||[]).filter(x=>x.fecha||x.actividades).forEach((m,i)=>{ if(!m.fecha||!m.actividades||!m.resultado)a.push(`Mantenimiento ${i+1}: complete fecha, actividad y resultado`); });
    if(d.retiro?.fecha && (!d.retiro.aprueba||!d.retiro.motivo))a.push("Retiro definitivo: complete aprobación y motivo");
  }
  if (tipo === "orden") {
    [[d.proyecto,"Proyecto"],[d.centroCosto,"Centro de costo"],[d.objetivo,"Objetivo"],[d.cliente,"Cliente"],[d.fechaInicio,"Fecha de inicio"],[d.fechaFin,"Fecha fin"],[d.responsable,"Responsable"],[d.autoriza,"Autoriza"]].forEach(([v,n])=>req(v,`Complete ${n}`));
    if(d.fechaInicio&&d.fechaFin&&d.fechaFin<d.fechaInicio)a.push("La fecha fin no puede ser anterior al inicio");
    (d.actividades||[]).filter(x=>x.descripcion).forEach((x,i)=>{ const q=num(x.cantidad),e=num(x.ejecutada),ad=num(x.adicional); if(q<=0)a.push(`Actividad ${i+1}: cantidad inválida`); if(e>q+ad)a.push(`Actividad ${i+1}: ejecutado supera cantidad + adicional`); if(ad>0&&!x.aprobacion)a.push(`Actividad ${i+1}: adicional sin aprobación`); });
    (d.requisitos||[]).forEach(x=>{ if(!x.cumple)a.push(`SST: responda requisito “${x.nombre}”`); if(x.cumple==="No"&&!x.observaciones)a.push(`SST: justifique “${x.nombre}”`); });
    (d.peligros||[]).forEach(x=>{ if(!x.presente)a.push(`Peligro pendiente: ${x.nombre}`); if(x.presente==="Sí"&&!x.observaciones)a.push(`Peligro sin medida de control: ${x.nombre}`); });
    (d.aspectos||[]).forEach(x=>{ if(!x.aplica)a.push(`Aspecto ambiental pendiente: ${x.nombre}`); if(x.aplica==="Sí"&&!x.observaciones)a.push(`Aspecto ambiental sin manejo: ${x.nombre}`); });
  }
  if (tipo === "liquidacion") {
    [[d.proceso,"Proceso"],[d.objeto,"Objeto del contrato"],[d.contratoNo,"Número de contrato"],[d.actaNo,"Consecutivo de acta"],[d.interventoria,"Interventoría"],[d.valorInicial,"Valor inicial"],[d.tipoObra,"Tipo de obra"],[d.fechaInicio,"Fecha de inicio"],[d.fechaTerminacion,"Fecha de terminación"],[d.fechaActa,"Fecha del acta"],[d.proyecto,"Nombre del proyecto"],[d.presupuestoNo,"Consecutivo presupuesto"],[d.valorLetras,"Valor en letras"]].forEach(([v,n])=>req(v,`Complete ${n}`));
    if(d.fechaInicio&&d.fechaTerminacion&&d.fechaTerminacion<d.fechaInicio)a.push("Fecha de terminación anterior a la fecha de inicio");
    const t=liquidacionTotales(d); if(t.acumulado>num(d.valorInicial)+num(d.valorAdicional))a.push("La liquidación acumulada supera el valor contractual disponible"); if(num(d.valorAcumuladoAnterior)&&Math.abs(t.acumulado-(num(d.valorAcumuladoAnterior)+t.presente))>1)a.push("La liquidación acumulada no concilia con acumulado anterior + presente");
    (d.lineas||[]).filter(x=>x.descripcion).forEach((x,i)=>{ if(num(x.cantidadAcumulada)<num(x.cantidadPresente))a.push(`Ítem ${i+1}: cantidad acumulada menor que la presente`); });
  }
  return a;
}

function materialStatus(x) { const q=num(x.cantidad), u=num(x.utilizado), d=num(x.devuelto); if(!x.descripcion)return "VACÍA"; if(q<=0||u+d>q||(d>0&&!x.fechaDev)||(x.fechaReq&&x.fechaEnt&&x.fechaEnt<x.fechaReq))return "REVISAR"; if(!x.fechaEnt)return "REQUERIDO"; if(u+d===q)return "CERRADO"; if(u+d===0)return "ENTREGADO"; return "EN OBRA"; }
function solicitudStatus(x) { if(!x.descripcion)return "SIN DILIGENCIAR"; const s=num(x.solicitada),u=num(x.utilizada),d=num(x.devuelta),f=num(x.facturada); if(s<=0||u+d>s||(f>0&&!x.factura)||(d>0&&!x.devolucion))return "REVISAR"; if(u+d===s)return "CONCILIADO"; return "EN PROCESO"; }
function actividadStatus(x) { if(!x.descripcion)return "SIN DILIGENCIAR"; const q=num(x.cantidad),e=num(x.ejecutada),ad=num(x.adicional); if(q<=0||e>q+ad||(ad>0&&!x.aprobacion))return "REVISAR"; if(e>=q+ad)return "COMPLETO"; return "PENDIENTE"; }
function liquidacionTotales(d) { const subtotalInicial=(d.lineas||[]).reduce((s,x)=>s+num(x.cantidadInicial)*num(x.valorUnitario),0); const subtotalPresente=(d.lineas||[]).reduce((s,x)=>s+num(x.cantidadPresente)*num(x.valorUnitario),0); const subtotalAcum=(d.lineas||[]).reduce((s,x)=>s+num(x.cantidadAcumulada)*num(x.valorUnitario),0); const calc=(sub,inc,aiu)=>sub+num(inc)+(sub+num(inc))*(num(aiu)/100); return { inicial:calc(subtotalInicial,d.incrementoInicial,d.aiuInicial), presente:calc(subtotalPresente,d.incrementoPresente,d.aiuPresente), acumulado:calc(subtotalAcum,d.incrementoAcumulado,d.aiuAcumulado), subtotalInicial, subtotalPresente, subtotalAcum }; }

function Icon({ name, size=20 }) { const p={ clipboard:"M9 5h6M9 9h6M9 13h4M7 3h10a2 2 0 0 1 2 2v16H5V5a2 2 0 0 1 2-2Z", tool:"M14.5 5.5a4 4 0 0 1-5 5L4 16l4 4 5.5-5.5a4 4 0 0 1 5-5", book:"M4 4h6a2 2 0 0 1 2 2v14a2 2 0 0 0-2-2H4V4Zm16 0h-6a2 2 0 0 0-2 2v14a2 2 0 0 1 2-2h6V4Z", box:"M21 8 12 3 3 8v8l9 5 9-5V8ZM3 8l9 5 9-5M12 13v9", truck:"M1 5h13v10H1V5Zm13 4h4l3 3v3h-7V9ZM6 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm12 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z", check:"M4 4h16v16H4V4Zm4 8 2.5 2.5L16 9", cash:"M2 7h20v10H2V7Zm10 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z", back:"M19 12H5m7 7-7-7 7-7", plus:"M12 5v14M5 12h14", trash:"M4 7h16M9 7V4h6v3m-9 0 1 14h10l1-14M10 11v6m4-6v6", print:"M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v7H6v-7Z"}[name]||"M4 12h16"; return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d={p}/></svg>; }
function Badge({ children, tone="gray" }) { const c={gray:"bg-gray-100 text-gray-600",blue:"bg-azul-soft text-azul",green:"bg-[#eaf3ee] text-[#0f6e56]",yellow:"bg-[#fdf6dd] text-[#7a5c00]",red:"bg-red-50 text-red-700"}[tone]; return <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-semibold ${c}`}>{children}</span>; }
function toneStatus(s){ if(["LISTO","CERRADO","CONCILIADO","COMPLETO","DEVUELTO","RETIRADO"].includes(s))return"green"; if(["REVISAR","INCOMPLETO"].includes(s))return"red"; if(["EN PROCESO","EN OBRA","ENTREGADO","PENDIENTE","EN DILIGENCIAMIENTO"].includes(s))return"yellow"; return"gray"; }
function Section({ n, title, help, children }) { return <Card className="overflow-hidden mb-5 animate-slide-up"><div className="px-5 py-3 border-b border-[#e5e7eb] bg-[#f9fafb] flex items-start gap-3"><div className="h-7 w-7 rounded-lg bg-azul text-white grid place-items-center text-xs font-bold shrink-0">{n}</div><div><h3 className="text-sm font-bold text-[#1a1a1a]">{title}</h3>{help&&<p className="text-xs text-gray-500 mt-0.5">{help}</p>}</div></div><div className="p-5">{children}</div></Card>; }
function Field({ label, value, onChange, required, type="text", options, textarea, placeholder, readOnly=false, className="" }) { return <div className={className}><label className="block text-xs font-semibold text-gray-500 mb-1.5">{label}{required&&<span className="text-red-500"> *</span>}</label>{options?<Select className="w-full" value={value??""} onChange={e=>onChange(e.target.value)} disabled={readOnly}><option value="">Selecciona...</option>{options.map(x=><option key={x} value={x}>{x}</option>)}</Select>:textarea?<textarea rows={3} className="w-full px-3 py-2.5 text-sm bg-white border border-[#d1d5db] rounded-lg outline-none transition focus:border-azul focus:ring-2 focus:ring-azul/25 resize-y" value={value??""} onChange={e=>onChange(e.target.value)} placeholder={placeholder} readOnly={readOnly}/>:<Input className="w-full" type={type} value={value??""} onChange={e=>onChange(e.target.value)} placeholder={placeholder} readOnly={readOnly}/>}</div>; }
function Grid({ children, cols=2 }) { return <div className={`grid grid-cols-1 ${cols===3?"md:grid-cols-3":cols===4?"md:grid-cols-4":"md:grid-cols-2"} gap-4`}>{children}</div>; }
function Stat({ label, value, accent=false }) { return <div className={`bg-white border rounded-xl p-4 ${accent?"border-amarillo":"border-[#e5e7eb]"}`}><div className="text-xs text-gray-500">{label}</div><div className="text-xl font-bold text-azul mt-1">{value}</div></div>; }
function AddRow({ onClick, label="Agregar fila" }) { return <button type="button" onClick={onClick} className="inline-flex items-center gap-1.5 text-xs font-semibold text-azul hover:underline mt-3"><Icon name="plus" size={15}/>{label}</button>; }
function Remove({ onClick }) { return <button type="button" onClick={onClick} title="Eliminar fila" className="p-1.5 text-gray-400 hover:text-red-600"><Icon name="trash" size={15}/></button>; }
function MiniInput({ value,onChange,type="text",className="" }) { return <input type={type} value={value??""} onChange={e=>onChange(e.target.value)} className={`w-full min-w-[80px] px-2 py-2 text-xs border border-[#d1d5db] rounded-lg outline-none focus:border-azul focus:ring-2 focus:ring-azul/20 ${className}`}/>; }
function MiniSelect({ value,onChange,options }) { return <select value={value??""} onChange={e=>onChange(e.target.value)} className="w-full min-w-[90px] px-2 py-2 text-xs border border-[#d1d5db] rounded-lg outline-none bg-white focus:border-azul"><option value="">—</option>{options.map(x=><option key={x}>{x}</option>)}</select>; }
function TableWrap({ children }) { return <div className="overflow-x-auto border border-[#e5e7eb] rounded-xl"><table className="w-full text-xs bg-white border-collapse">{children}</table></div>; }
const Th=({children})=><th className="px-2.5 py-2.5 text-left bg-azul text-white font-semibold whitespace-nowrap">{children}</th>;
const Td=({children,className=""})=><td className={`px-2 py-2 border-b border-[#eef0f2] align-top ${className}`}>{children}</td>;

function Bitacora({d,set}) { const setRow=(i,k,v)=>set({...d,cantidades:d.cantidades.map((x,j)=>j===i?{...x,[k]:v}:x)}); const total=d.cantidades.reduce((s,x)=>s+num(x.cantidad),0); return <><div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5"><Stat label="Fecha" value={d.fecha||"—"}/><Stat label="Ítems instalados" value={d.cantidades.filter(x=>x.descripcion).length}/><Stat label="Cantidad total" value={total}/><Stat label="Estado" value={validate("bitacora",d).length?"REVISAR":"LISTO"} accent/></div><Section n="01" title="Datos generales" help="Identifique la jornada y el proyecto."><Grid><Field label="Fecha" type="date" required value={d.fecha} onChange={v=>set({...d,fecha:v})}/><Field label="Nombre del proyecto" required value={d.proyecto} onChange={v=>set({...d,proyecto:v})}/><Field className="md:col-span-2" label="Integrantes de la cuadrilla" required textarea value={d.cuadrilla} onChange={v=>set({...d,cuadrilla:v})} placeholder="Nombres o cuadrilla asignada"/><Field label="Ubicación / frente (opcional)" value={d.ubicacion} onChange={v=>set({...d,ubicacion:v})}/><Field label="Condiciones de la jornada (opcional)" value={d.condiciones} onChange={v=>set({...d,condiciones:v})} placeholder="Clima, acceso, restricciones..."/></Grid></Section><Section n="02" title="Novedades relevantes" help="Registre lo que ocurrió o afectó la jornada. Si no hubo, escriba “Sin novedades”."><Field label="Novedades del día" required textarea value={d.novedades} onChange={v=>set({...d,novedades:v})}/></Section><Section n="03" title="Procedimiento del día" help="Describa claramente qué actividades se ejecutaron."><Field label="Actividades ejecutadas" required textarea value={d.procedimiento} onChange={v=>set({...d,procedimiento:v})}/></Section><Section n="04" title="Actividades pendientes" help="Pendientes según cronograma o directrices; si no hay, escriba “Sin pendientes”."><Field label="Pendientes" required textarea value={d.pendientes} onChange={v=>set({...d,pendientes:v})}/></Section><Section n="05" title="Cantidades instaladas" help="Una fila por material o actividad cuantificable."><TableWrap><thead><tr><Th>Descripción / material</Th><Th>Cantidad</Th><Th>U/M</Th><Th>Observaciones</Th><Th></Th></tr></thead><tbody>{d.cantidades.map((x,i)=><tr key={x.id}><Td><MiniInput value={x.descripcion} onChange={v=>setRow(i,"descripcion",v)}/></Td><Td><MiniInput type="number" value={x.cantidad} onChange={v=>setRow(i,"cantidad",v)}/></Td><Td><MiniSelect value={x.unidad} options={UNIDADES} onChange={v=>setRow(i,"unidad",v)}/></Td><Td><MiniInput value={x.observaciones} onChange={v=>setRow(i,"observaciones",v)}/></Td><Td><Remove onClick={()=>set({...d,cantidades:d.cantidades.filter((_,j)=>j!==i)})}/></Td></tr>)}</tbody></TableWrap><AddRow onClick={()=>set({...d,cantidades:[...d.cantidades,{id:uid(),descripcion:"",cantidad:"",unidad:"UND",observaciones:""}]})}/></Section><Section n="06" title="Firmas / responsables" help="Identifique quién valida el registro."><Grid><Field label="Responsable de la obra" value={d.responsable} onChange={v=>set({...d,responsable:v})}/><Field label="Tercero / interventoría / encargado" value={d.tercero} onChange={v=>set({...d,tercero:v})}/></Grid></Section></>; }

function ControlMaterial({d,set}) { const setRow=(i,k,v)=>set({...d,lineas:d.lineas.map((x,j)=>j===i?{...x,[k]:v}:x)}); const active=d.lineas.filter(x=>x.descripcion); const sums=active.reduce((s,x)=>({q:s.q+num(x.cantidad),u:s.u+num(x.utilizado),dv:s.dv+num(x.devuelto)}),{q:0,u:0,dv:0}); return <><div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-5"><Stat label="Líneas" value={active.length}/><Stat label="Requerido" value={sums.q}/><Stat label="Utilizado" value={sums.u}/><Stat label="Devuelto" value={sums.dv}/><Stat label="Saldo" value={sums.q-sums.u-sums.dv} accent/></div><Section n="01" title="Datos del proyecto"><Grid cols={4}><Field label="Proyecto" required value={d.proyecto} onChange={v=>set({...d,proyecto:v})}/><Field label="Fecha inicio de obra" type="date" required value={d.fechaInicio} onChange={v=>set({...d,fechaInicio:v})}/><Field label="Destino" required value={d.destino} onChange={v=>set({...d,destino:v})}/><Field label="Sucursal" required value={d.sucursal} onChange={v=>set({...d,sucursal:v})}/></Grid></Section><Section n="02" title="Registro de materiales" help="Una línea por entrega/requerimiento. El saldo y estado son automáticos."><TableWrap><thead><tr>{["Factura","Bodega","Requisición","Código","Descripción","U/M","Cant.","F. req.","F. ent.","Entregado por","Recibido por","Util.","Dev.","F. dev.","Saldo","Estado",""] .map(h=><Th key={h}>{h}</Th>)}</tr></thead><tbody>{d.lineas.map((x,i)=>{const saldo=num(x.cantidad)-num(x.utilizado)-num(x.devuelto),st=materialStatus(x);return <tr key={x.id}><Td><MiniInput value={x.factura} onChange={v=>setRow(i,"factura",v)}/></Td><Td><MiniSelect value={x.bodega} options={BODEGAS} onChange={v=>setRow(i,"bodega",v)}/></Td><Td><MiniInput value={x.requisicion} onChange={v=>setRow(i,"requisicion",v)}/></Td><Td><MiniInput value={x.codigo} onChange={v=>setRow(i,"codigo",v)}/></Td><Td><MiniInput value={x.descripcion} onChange={v=>setRow(i,"descripcion",v)}/></Td><Td><MiniSelect value={x.unidad} options={UNIDADES} onChange={v=>setRow(i,"unidad",v)}/></Td><Td><MiniInput type="number" value={x.cantidad} onChange={v=>setRow(i,"cantidad",v)}/></Td><Td><MiniInput type="date" value={x.fechaReq} onChange={v=>setRow(i,"fechaReq",v)}/></Td><Td><MiniInput type="date" value={x.fechaEnt} onChange={v=>setRow(i,"fechaEnt",v)}/></Td><Td><MiniInput value={x.entregadoPor} onChange={v=>setRow(i,"entregadoPor",v)}/></Td><Td><MiniInput value={x.recibidoPor} onChange={v=>setRow(i,"recibidoPor",v)}/></Td><Td><MiniInput type="number" value={x.utilizado} onChange={v=>setRow(i,"utilizado",v)}/></Td><Td><MiniInput type="number" value={x.devuelto} onChange={v=>setRow(i,"devuelto",v)}/></Td><Td><MiniInput type="date" value={x.fechaDev} onChange={v=>setRow(i,"fechaDev",v)}/></Td><Td className="font-semibold">{x.descripcion?saldo:"—"}</Td><Td><Badge tone={toneStatus(st)}>{st}</Badge></Td><Td><Remove onClick={()=>set({...d,lineas:d.lineas.filter((_,j)=>j!==i)})}/></Td></tr>})}</tbody></TableWrap><AddRow onClick={()=>set({...d,lineas:[...d.lineas,{id:uid(),factura:"",bodega:"",requisicion:"",codigo:"",descripcion:"",unidad:"UND",cantidad:"",fechaReq:"",fechaEnt:"",entregadoPor:"",recibidoPor:"",utilizado:"",devuelto:"",fechaDev:""}]})}/><p className="text-xs text-gray-500 mt-3">Una línea queda CERRADA cuando utilizado + devuelto = cantidad requerida. Si existe devolución, la fecha de devolución es obligatoria.</p></Section></>; }

function SolicitudMateriales({d,set}) { const setRow=(i,k,v)=>set({...d,lineas:d.lineas.map((x,j)=>j===i?{...x,[k]:v}:x)}); const active=d.lineas.filter(x=>x.descripcion); const totals=active.reduce((s,x)=>({s:s.s+num(x.solicitada),f:s.f+num(x.facturada),u:s.u+num(x.utilizada),dv:s.dv+num(x.devuelta)}),{s:0,f:0,u:0,dv:0}); return <><div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-5"><Stat label="Ítems" value={active.length}/><Stat label="Solicitado" value={totals.s}/><Stat label="Facturado" value={totals.f}/><Stat label="Utilizado" value={totals.u}/><Stat label="Saldo" value={totals.s-totals.u-totals.dv} accent/></div><Section n="01" title="Datos de la solicitud"><Grid cols={3}><Field label="Fecha" type="date" required value={d.fecha} onChange={v=>set({...d,fecha:v})}/><Field label="Proyecto" required value={d.proyecto} onChange={v=>set({...d,proyecto:v})}/><Field label="Responsable" required value={d.responsable} onChange={v=>set({...d,responsable:v})}/></Grid></Section><Section n="02" title="Registro de materiales" help="Actualice facturado, utilizado, devuelto y soportes a medida que avanza la gestión."><TableWrap><thead><tr>{["Descripción","U/M","Solicitada","Facturada","Utilizada","Devuelta","No. factura","No. devolución","Observaciones","Saldo","Estado",""] .map(h=><Th key={h}>{h}</Th>)}</tr></thead><tbody>{d.lineas.map((x,i)=>{const saldo=num(x.solicitada)-num(x.utilizada)-num(x.devuelta),st=solicitudStatus(x);return <tr key={x.id}><Td><MiniInput value={x.descripcion} onChange={v=>setRow(i,"descripcion",v)}/></Td><Td><MiniSelect value={x.unidad} options={UNIDADES} onChange={v=>setRow(i,"unidad",v)}/></Td><Td><MiniInput type="number" value={x.solicitada} onChange={v=>setRow(i,"solicitada",v)}/></Td><Td><MiniInput type="number" value={x.facturada} onChange={v=>setRow(i,"facturada",v)}/></Td><Td><MiniInput type="number" value={x.utilizada} onChange={v=>setRow(i,"utilizada",v)}/></Td><Td><MiniInput type="number" value={x.devuelta} onChange={v=>setRow(i,"devuelta",v)}/></Td><Td><MiniInput value={x.factura} onChange={v=>setRow(i,"factura",v)}/></Td><Td><MiniInput value={x.devolucion} onChange={v=>setRow(i,"devolucion",v)}/></Td><Td><MiniInput value={x.observaciones} onChange={v=>setRow(i,"observaciones",v)}/></Td><Td className="font-semibold">{x.descripcion?saldo:"—"}</Td><Td><Badge tone={toneStatus(st)}>{st}</Badge></Td><Td><Remove onClick={()=>set({...d,lineas:d.lineas.filter((_,j)=>j!==i)})}/></Td></tr>})}</tbody></TableWrap><AddRow onClick={()=>set({...d,lineas:[...d.lineas,{id:uid(),descripcion:"",unidad:"UND",solicitada:"",facturada:"",utilizada:"",devuelta:"",factura:"",devolucion:"",observaciones:""}]})}/></Section><Section n="03" title="Observación general"><Field label="Observación" textarea value={d.observacionGeneral} onChange={v=>set({...d,observacionGeneral:v})}/></Section></>; }

function Finalizacion({d,set}) { const days=d.fechaActa&&d.fechaFinalizacion?Math.round((new Date(d.fechaActa)-new Date(d.fechaFinalizacion))/86400000):null; const vari=num(d.valorFinal)-num(d.valorContrato); return <><div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5"><Stat label="Etapa" value={d.etapaActa||"—"}/><Stat label="Días cierre → acta" value={days??"—"}/><Stat label="Variación final" value={d.valorFinal&&d.valorContrato?money(vari):"—"}/><Stat label="Estado" value={validate("finalizacion",d).length?"REVISAR":"LISTO"} accent/></div><Section n="01" title="Datos generales del acta"><Grid><Field label="Fecha del acta" type="date" required value={d.fechaActa} onChange={v=>set({...d,fechaActa:v})}/><Field label="Código / Proyecto" required value={d.codigoProyecto} onChange={v=>set({...d,codigoProyecto:v})}/><Field label="Ciudad" required value={d.ciudad} onChange={v=>set({...d,ciudad:v})}/><Field label="Etapa del acta" required options={["Borrador","En revisión","Listo para firma","Firmado"]} value={d.etapaActa} onChange={v=>set({...d,etapaActa:v})}/><Field className="md:col-span-2" label="Obra / objeto contractual" required textarea value={d.objeto} onChange={v=>set({...d,objeto:v})}/><Field label="Código documento" value={d.codigoDocumento} onChange={v=>set({...d,codigoDocumento:v})}/><Field label="Versión" value={d.version} onChange={v=>set({...d,version:v})}/></Grid></Section><Section n="02" title="Contrato y cierre"><Grid cols={3}><Field label="Contratista" required value={d.contratista} onChange={v=>set({...d,contratista:v})}/><Field label="NIT" required value={d.nit} onChange={v=>set({...d,nit:v})}/><Field label="Ciudad contratista" value={d.ciudadContratista} onChange={v=>set({...d,ciudadContratista:v})}/><Field label="Contrato No." required value={d.contratoNo} onChange={v=>set({...d,contratoNo:v})}/><Field label="Fecha del contrato" type="date" required value={d.fechaContrato} onChange={v=>set({...d,fechaContrato:v})}/><Field label="Valor contrato" type="number" required value={d.valorContrato} onChange={v=>set({...d,valorContrato:v})}/><Field label="Fecha de finalización" type="date" required value={d.fechaFinalizacion} onChange={v=>set({...d,fechaFinalizacion:v})}/><Field label="Valor final contrato" type="number" required value={d.valorFinal} onChange={v=>set({...d,valorFinal:v})}/><Field label="Recibo a satisfacción" required options={SI_NO_OBS} value={d.recibo} onChange={v=>set({...d,recibo:v})}/></Grid></Section><Section n="03" title="Responsables y firmantes"><Grid cols={3}><Field label="Rep. contratista" required value={d.repContratista} onChange={v=>set({...d,repContratista:v})}/><Field label="Cargo" value={d.cargoContratista} onChange={v=>set({...d,cargoContratista:v})}/><Field label="Contratante" required value={d.contratante} onChange={v=>set({...d,contratante:v})}/><Field label="Rep. contratante 1" required value={d.repContratante1} onChange={v=>set({...d,repContratante1:v})}/><Field label="Rep. contratante 2" value={d.repContratante2} onChange={v=>set({...d,repContratante2:v})}/><Field label="Interventor" required value={d.interventor} onChange={v=>set({...d,interventor:v})}/><Field label="Empresa interventoría" value={d.empresaInterventoria} onChange={v=>set({...d,empresaInterventoria:v})}/><Field label="Ciudad contratante" value={d.ciudadContratante} onChange={v=>set({...d,ciudadContratante:v})}/></Grid></Section><Section n="04" title="Validación técnica y observaciones"><Grid><Field label="Cumple especificaciones" required options={SI_NO_OBS} value={d.cumple} onChange={v=>set({...d,cumple:v})}/><Field label="Pendientes abiertos" options={["Sí","No"]} value={d.pendientesAbiertos} onChange={v=>set({...d,pendientesAbiertos:v})}/><Field className="md:col-span-2" label="Observaciones / pendientes" textarea value={d.observaciones} onChange={v=>set({...d,observaciones:v})}/></Grid></Section></>; }

function Herramienta({d,set}) { const setMaint=(i,k,v)=>set({...d,mantenimientos:d.mantenimientos.map((x,j)=>j===i?{...x,[k]:v}:x)}); const datos=<Grid cols={3}><Field label="Nombre" required value={d.nombre} onChange={v=>set({...d,nombre:v})}/><Field label="Marca" required value={d.marca} onChange={v=>set({...d,marca:v})}/><Field label="Referencia" required value={d.referencia} onChange={v=>set({...d,referencia:v})}/><Field className="md:col-span-2" label="Descripción" required value={d.descripcion} onChange={v=>set({...d,descripcion:v})}/><Field label="No. de serie" required value={d.serial} onChange={v=>set({...d,serial:v})}/><Field label="Fecha de adquisición" type="date" required value={d.fechaAdquisicion} onChange={v=>set({...d,fechaAdquisicion:v})}/></Grid>; const maintenance=<><TableWrap><thead><tr><Th>Fecha</Th><Th>Tipo</Th><Th>Actividades desarrolladas</Th><Th>Resultado</Th><Th></Th></tr></thead><tbody>{d.mantenimientos.map((m,i)=><tr key={m.id}><Td><MiniInput type="date" value={m.fecha} onChange={v=>setMaint(i,"fecha",v)}/></Td><Td><MiniSelect value={m.tipo} options={MANTENIMIENTOS} onChange={v=>setMaint(i,"tipo",v)}/></Td><Td><MiniInput value={m.actividades} onChange={v=>setMaint(i,"actividades",v)}/></Td><Td><MiniSelect value={m.resultado} options={RESULTADOS_MANT} onChange={v=>setMaint(i,"resultado",v)}/></Td><Td><Remove onClick={()=>set({...d,mantenimientos:d.mantenimientos.filter((_,j)=>j!==i)})}/></Td></tr>)}</tbody></TableWrap><AddRow label="Agregar mantenimiento" onClick={()=>set({...d,mantenimientos:[...d.mantenimientos,{id:uid(),fecha:"",tipo:"Preventivo",actividades:"",resultado:"Conforme"}]})}/></>; const movement=(m,mi)=>{const setM=(part,k,v)=>set({...d,movimientos:d.movimientos.map((x,j)=>j===mi?{...x,[part]:{...x[part],[k]:v}}:x)});const setTool=(ti,k,v)=>set({...d,movimientos:d.movimientos.map((x,j)=>j===mi?{...x,herramientas:x.herramientas.map((t,z)=>z===ti?{...t,[k]:v}:t)}:x)});return <Section key={m.id} n={`M${m.numero}`} title={`Movimiento ${m.numero}`} help="Registre primero las herramientas y después la entrega/devolución."><TableWrap><thead><tr>{["Nombre","Descripción","Marca","Referencia","Serie","Cant.",""] .map(h=><Th key={h}>{h}</Th>)}</tr></thead><tbody>{m.herramientas.map((t,ti)=><tr key={t.id}><Td><MiniInput value={t.nombre} onChange={v=>setTool(ti,"nombre",v)}/></Td><Td><MiniInput value={t.descripcion} onChange={v=>setTool(ti,"descripcion",v)}/></Td><Td><MiniInput value={t.marca} onChange={v=>setTool(ti,"marca",v)}/></Td><Td><MiniInput value={t.referencia} onChange={v=>setTool(ti,"referencia",v)}/></Td><Td><MiniInput value={t.serial} onChange={v=>setTool(ti,"serial",v)}/></Td><Td><MiniInput type="number" value={t.cantidad} onChange={v=>setTool(ti,"cantidad",v)}/></Td><Td><Remove onClick={()=>set({...d,movimientos:d.movimientos.map((x,j)=>j===mi?{...x,herramientas:x.herramientas.filter((_,z)=>z!==ti)}:x)})}/></Td></tr>)}</tbody></TableWrap><AddRow label="Agregar herramienta" onClick={()=>set({...d,movimientos:d.movimientos.map((x,j)=>j===mi?{...x,herramientas:[...x.herramientas,{id:uid(),nombre:"",descripcion:"",marca:"",referencia:"",serial:"",cantidad:1}]}:x)})}/><div className="grid grid-cols-1 md:grid-cols-2 gap-5 mt-5"><div className="p-4 bg-[#f9fafb] rounded-xl"><div className="text-xs font-bold text-azul mb-3">ENTREGA</div><Grid><Field label="Fecha" type="date" value={m.entrega.fecha} onChange={v=>setM("entrega","fecha",v)}/><Field label="Quien entrega" value={m.entrega.entrega} onChange={v=>setM("entrega","entrega",v)}/><Field label="Quien recibe" value={m.entrega.recibe} onChange={v=>setM("entrega","recibe",v)}/><Field label="Observaciones" value={m.entrega.observaciones} onChange={v=>setM("entrega","observaciones",v)}/></Grid></div><div className="p-4 bg-[#f9fafb] rounded-xl"><div className="text-xs font-bold text-azul mb-3">DEVOLUCIÓN</div><Grid><Field label="Fecha" type="date" value={m.devolucion.fecha} onChange={v=>setM("devolucion","fecha",v)}/><Field label="Quien devuelve" value={m.devolucion.entrega} onChange={v=>setM("devolucion","entrega",v)}/><Field label="Quien recibe" value={m.devolucion.recibe} onChange={v=>setM("devolucion","recibe",v)}/><Field label="Observaciones" value={m.devolucion.observaciones} onChange={v=>setM("devolucion","observaciones",v)}/></Grid></div></div></Section>}; return <><Section n="00" title="Modalidad del formato" help="H1: ficha individual + mantenimiento · H2: movimientos por grupo · AP: tenencia + mantenimiento + retiro."><div className="max-w-sm"><Field label="Modalidad" options={["H1","H2","AP"]} value={d.modalidad} onChange={v=>set({...defaults("herramienta"),modalidad:v})}/></div></Section>{d.modalidad!=="H2"&&<Section n="01" title="Datos generales" help="Identifique el equipo o herramienta.">{datos}</Section>}{d.modalidad==="AP"&&<Section n="02" title="Seguimiento a la tenencia"><Grid cols={4}><Field label="Fecha entrega" type="date" value={d.entrega.fecha} onChange={v=>set({...d,entrega:{...d.entrega,fecha:v}})}/><Field label="Quien entrega" value={d.entrega.entrega} onChange={v=>set({...d,entrega:{...d.entrega,entrega:v}})}/><Field label="Quien recibe" value={d.entrega.recibe} onChange={v=>set({...d,entrega:{...d.entrega,recibe:v}})}/><Field label="Observaciones" value={d.entrega.observaciones} onChange={v=>set({...d,entrega:{...d.entrega,observaciones:v}})}/><Field label="Fecha devolución" type="date" value={d.devolucion.fecha} onChange={v=>set({...d,devolucion:{...d.devolucion,fecha:v}})}/><Field label="Quien devuelve" value={d.devolucion.entrega} onChange={v=>set({...d,devolucion:{...d.devolucion,entrega:v}})}/><Field label="Quien recibe" value={d.devolucion.recibe} onChange={v=>set({...d,devolucion:{...d.devolucion,recibe:v}})}/><Field label="Observaciones" value={d.devolucion.observaciones} onChange={v=>set({...d,devolucion:{...d.devolucion,observaciones:v}})}/></Grid></Section>}{d.modalidad==="H2"&&d.movimientos.map(movement)}{d.modalidad!=="H2"&&<Section n={d.modalidad==="AP"?"03":"02"} title="Seguimiento de mantenimiento" help="Una fila por intervención.">{maintenance}</Section>}{d.modalidad!=="H2"&&<Section n={d.modalidad==="AP"?"04":"03"} title="Observaciones"><Field label="Novedades o recomendaciones" textarea value={d.observaciones} onChange={v=>set({...d,observaciones:v})}/></Section>}{d.modalidad!=="H2"&&<Section n={d.modalidad==="AP"?"05":"04"} title="Retiro definitivo" help="Complete únicamente cuando el equipo/herramienta salga de servicio."><Grid cols={4}><Field label="Fecha retiro" type="date" value={d.retiro.fecha} onChange={v=>set({...d,retiro:{...d.retiro,fecha:v}})}/><Field label="Aprueba" value={d.retiro.aprueba} onChange={v=>set({...d,retiro:{...d.retiro,aprueba:v}})}/><Field label="Motivo" value={d.retiro.motivo} onChange={v=>set({...d,retiro:{...d.retiro,motivo:v}})}/><Field label="Firma / constancia" value={d.retiro.firma} onChange={v=>set({...d,retiro:{...d.retiro,firma:v}})}/></Grid></Section>}</>; }

function Orden({d,set}) { const setAct=(i,k,v)=>set({...d,actividades:d.actividades.map((x,j)=>j===i?{...x,[k]:v}:x)}); const toggleTipo=t=>set({...d,tipos:d.tipos.includes(t)?d.tipos.filter(x=>x!==t):[...d.tipos,t]}); const setList=(key,i,k,v)=>set({...d,[key]:d[key].map((x,j)=>j===i?{...x,[k]:v}:x)}); const types=["Construcción","Diseño","Entrega de obra","PQR","Ejecución","Montaje","Mantenimiento","Visita","Otro"]; return <><div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5"><Stat label="Actividades" value={d.actividades.filter(x=>x.descripcion).length}/><Stat label="Completas" value={d.actividades.filter(x=>actividadStatus(x)==="COMPLETO").length}/><Stat label="SST / Ambiental" value={`${d.peligros.filter(x=>x.presente==="Sí").length + d.aspectos.filter(x=>x.aplica==="Sí").length} identificados`}/><Stat label="Estado" value={validate("orden",d).length?"REVISAR":"LISTO"} accent/></div><Section n="01" title="Datos generales" help="Identifique proyecto, cliente, fechas y responsables."><Grid cols={3}><Field label="Proyecto" required value={d.proyecto} onChange={v=>set({...d,proyecto:v})}/><Field label="Centro de costo" required value={d.centroCosto} onChange={v=>set({...d,centroCosto:v})}/><Field label="Visita técnica" options={["Sí","No","No aplica"]} value={d.visitaTecnica} onChange={v=>set({...d,visitaTecnica:v})}/><Field className="md:col-span-2" label="Objetivo" required textarea value={d.objetivo} onChange={v=>set({...d,objetivo:v})}/><Field label="Cliente" required value={d.cliente} onChange={v=>set({...d,cliente:v})}/><Field label="Fecha inicio" type="date" required value={d.fechaInicio} onChange={v=>set({...d,fechaInicio:v})}/><Field label="Fecha fin" type="date" required value={d.fechaFin} onChange={v=>set({...d,fechaFin:v})}/><Field label="Responsable" required value={d.responsable} onChange={v=>set({...d,responsable:v})}/><Field label="Autoriza" required value={d.autoriza} onChange={v=>set({...d,autoriza:v})}/></Grid></Section><Section n="02" title="Tipo de proyecto" help="Seleccione únicamente los tipos que correspondan."><div className="flex flex-wrap gap-2">{types.map(t=><button key={t} type="button" onClick={()=>toggleTipo(t)} className={`px-3 py-2 rounded-lg border text-xs font-semibold transition ${d.tipos.includes(t)?"bg-azul text-white border-azul":"bg-white text-gray-600 border-[#d1d5db] hover:border-azul"}`}>{t}</button>)}</div>{d.tipos.includes("Otro")&&<div className="mt-3 max-w-md"><Field label="Otro / detalle" value={d.otroTipo} onChange={v=>set({...d,otroTipo:v})}/></div>}</Section><Section n="03" title="Actividades / alcance" help="Una fila por actividad. Saldo, % ejecutado y estado son automáticos."><TableWrap><thead><tr>{["Descripción","U/M","Cant.","Ejecutada","Adicional","Aprobación adicional","Observaciones","Saldo","% ejec.","Estado",""] .map(h=><Th key={h}>{h}</Th>)}</tr></thead><tbody>{d.actividades.map((x,i)=>{const total=num(x.cantidad)+num(x.adicional),saldo=total-num(x.ejecutada),pe=total?Math.min(100,(num(x.ejecutada)/total)*100):0,st=actividadStatus(x);return <tr key={x.id}><Td><MiniInput value={x.descripcion} onChange={v=>setAct(i,"descripcion",v)}/></Td><Td><MiniSelect value={x.unidad} options={UNIDADES} onChange={v=>setAct(i,"unidad",v)}/></Td><Td><MiniInput type="number" value={x.cantidad} onChange={v=>setAct(i,"cantidad",v)}/></Td><Td><MiniInput type="number" value={x.ejecutada} onChange={v=>setAct(i,"ejecutada",v)}/></Td><Td><MiniInput type="number" value={x.adicional} onChange={v=>setAct(i,"adicional",v)}/></Td><Td><MiniInput value={x.aprobacion} onChange={v=>setAct(i,"aprobacion",v)}/></Td><Td><MiniInput value={x.observaciones} onChange={v=>setAct(i,"observaciones",v)}/></Td><Td>{x.descripcion?saldo:"—"}</Td><Td>{x.descripcion?`${pe.toFixed(0)}%`:"—"}</Td><Td><Badge tone={toneStatus(st)}>{st}</Badge></Td><Td><Remove onClick={()=>set({...d,actividades:d.actividades.filter((_,j)=>j!==i)})}/></Td></tr>})}</tbody></TableWrap><AddRow onClick={()=>set({...d,actividades:[...d.actividades,{id:uid(),descripcion:"",unidad:"UND",cantidad:"",ejecutada:"",adicional:"",aprobacion:"",observaciones:""}]})}/></Section><Section n="04" title="Riesgos de calidad"><Field label="Riesgos, controles o condiciones relevantes" textarea value={d.riesgosCalidad} onChange={v=>set({...d,riesgosCalidad:v})}/></Section><Section n="05" title="SST / requisitos del lugar" help="Control operativo previo. No sustituye la matriz formal de peligros, permisos de trabajo ni procedimientos SST aplicables."><TableWrap><thead><tr><Th>Requisito</Th><Th>¿Cumple?</Th><Th>Observaciones / soporte</Th><Th>Estado</Th></tr></thead><tbody>{d.requisitos.map((x,i)=>{const st=!x.cumple?"PENDIENTE":x.cumple==="No"&&!x.observaciones?"REVISAR":"OK";return <tr key={x.id}><Td className="font-medium">{x.nombre}</Td><Td><MiniSelect value={x.cumple} options={SI_NO_NA.filter(Boolean)} onChange={v=>setList("requisitos",i,"cumple",v)}/></Td><Td><MiniInput value={x.observaciones} onChange={v=>setList("requisitos",i,"observaciones",v)}/></Td><Td><Badge tone={toneStatus(st)}>{st}</Badge></Td></tr>})}</tbody></TableWrap></Section><Section n="06" title="Identificación de peligros" help="Si marca Sí, registre la medida de prevención/control aplicada."><TableWrap><thead><tr><Th>Categoría</Th><Th>Peligro / condición</Th><Th>¿Presente?</Th><Th>Observación / medida de control</Th><Th>Estado</Th></tr></thead><tbody>{d.peligros.map((x,i)=>{const st=!x.presente?"PENDIENTE":x.presente==="Sí"&&!x.observaciones?"REVISAR":"OK";return <tr key={x.id}><Td className="font-semibold text-gray-500">{x.categoria}</Td><Td>{x.nombre}</Td><Td><MiniSelect value={x.presente} options={SI_NO_NA.filter(Boolean)} onChange={v=>setList("peligros",i,"presente",v)}/></Td><Td><MiniInput value={x.observaciones} onChange={v=>setList("peligros",i,"observaciones",v)}/></Td><Td><Badge tone={toneStatus(st)}>{st}</Badge></Td></tr>})}</tbody></TableWrap></Section><Section n="07" title="Aspectos ambientales" help="Todo aspecto aplicable debe indicar la medida de manejo o control."><TableWrap><thead><tr><Th>Aspecto ambiental</Th><Th>¿Aplica?</Th><Th>Observación / manejo</Th><Th>Estado</Th></tr></thead><tbody>{d.aspectos.map((x,i)=>{const st=!x.aplica?"PENDIENTE":x.aplica==="Sí"&&!x.observaciones?"REVISAR":"OK";return <tr key={x.id}><Td>{x.nombre}</Td><Td><MiniSelect value={x.aplica} options={SI_NO_NA.filter(Boolean)} onChange={v=>setList("aspectos",i,"aplica",v)}/></Td><Td><MiniInput value={x.observaciones} onChange={v=>setList("aspectos",i,"observaciones",v)}/></Td><Td><Badge tone={toneStatus(st)}>{st}</Badge></Td></tr>})}</tbody></TableWrap><div className="mt-4"><Field label="Otras observaciones SST / ambientales" textarea value={d.observacionesSst} onChange={v=>set({...d,observacionesSst:v})}/></div></Section><Section n="08" title="Cierre y firmas"><Grid><Field label="Responsable de la obra" value={d.firmaResponsable} onChange={v=>set({...d,firmaResponsable:v})}/><Field label="Quien recibe la obra" value={d.firmaRecibe} onChange={v=>set({...d,firmaRecibe:v})}/></Grid></Section></>; }

function Liquidacion({d,set}) { const setRow=(i,k,v)=>set({...d,lineas:d.lineas.map((x,j)=>j===i?{...x,[k]:v}:x)}); const t=liquidacionTotales(d); const anticipo=num(d.valorInicial)*(num(d.anticipoPct)/100); return <><div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5"><Stat label="Presupuesto inicial" value={money(t.inicial)}/><Stat label="Liquidación presente" value={money(t.presente)}/><Stat label="Liquidación acumulada" value={money(t.acumulado)}/><Stat label="Disponible contrato" value={money(num(d.valorInicial)+num(d.valorAdicional)-t.acumulado)} accent/></div><Section n="01" title="Datos generales del contrato y del acta"><Grid cols={3}><Field label="Proceso" required value={d.proceso} onChange={v=>set({...d,proceso:v})}/><Field className="md:col-span-2" label="Objeto del contrato" required value={d.objeto} onChange={v=>set({...d,objeto:v})}/><Field label="Número de contrato" required value={d.contratoNo} onChange={v=>set({...d,contratoNo:v})}/><Field label="Consecutivo de acta" required value={d.actaNo} onChange={v=>set({...d,actaNo:v})}/><Field label="Interventoría" required value={d.interventoria} onChange={v=>set({...d,interventoria:v})}/><Field label="Valor inicial contrato" type="number" required value={d.valorInicial} onChange={v=>set({...d,valorInicial:v})}/><Field label="Tipo de obra" required value={d.tipoObra} onChange={v=>set({...d,tipoObra:v})}/><Field label="Fecha inicio" type="date" required value={d.fechaInicio} onChange={v=>set({...d,fechaInicio:v})}/><Field label="Fecha terminación" type="date" required value={d.fechaTerminacion} onChange={v=>set({...d,fechaTerminacion:v})}/><Field label="Fecha del acta" type="date" required value={d.fechaActa} onChange={v=>set({...d,fechaActa:v})}/><Field label="Valor adicional contrato" type="number" value={d.valorAdicional} onChange={v=>set({...d,valorAdicional:v})}/><Field label="Anticipo %" type="number" value={d.anticipoPct} onChange={v=>set({...d,anticipoPct:v})}/><Field label="Valor acumulado anterior" type="number" value={d.valorAcumuladoAnterior} onChange={v=>set({...d,valorAcumuladoAnterior:v})}/><Field label="Valor anticipo (automático)" readOnly value={money(anticipo)} onChange={()=>{}}/><Field label="Fecha anticipo" type="date" value={d.fechaAnticipo} onChange={v=>set({...d,fechaAnticipo:v})}/><Field label="Concesión" value={d.concesion} onChange={v=>set({...d,concesion:v})}/></Grid></Section><Section n="02" title="Identificación del proyecto"><Grid cols={3}><Field label="Nombre del proyecto" required value={d.proyecto} onChange={v=>set({...d,proyecto:v})}/><Field label="Visita técnica" options={["Sí","No","No aplica"]} value={d.visitaTecnica} onChange={v=>set({...d,visitaTecnica:v})}/><Field label="Ubicación" options={["Urbano","Rural","Mixto"]} value={d.ubicacion} onChange={v=>set({...d,ubicacion:v})}/><Field label="Consecutivo presupuesto" required value={d.presupuestoNo} onChange={v=>set({...d,presupuestoNo:v})}/></Grid></Section><Section n="03" title="Detalle económico" help="La cantidad acumulada refleja el avance real acumulado. Los valores se calculan en tiempo real."><TableWrap><thead><tr>{["Código","Descripción","U/M","Cant. inicial","V. unitario","V. total inicial","Cant. presente","V. total presente","Cant. acumulada","V. total acum.",""] .map(h=><Th key={h}>{h}</Th>)}</tr></thead><tbody>{d.lineas.map((x,i)=><tr key={x.id}><Td><MiniInput value={x.codigo} onChange={v=>setRow(i,"codigo",v)}/></Td><Td><MiniInput value={x.descripcion} onChange={v=>setRow(i,"descripcion",v)}/></Td><Td><MiniSelect value={x.unidad} options={UNIDADES} onChange={v=>setRow(i,"unidad",v)}/></Td><Td><MiniInput type="number" value={x.cantidadInicial} onChange={v=>setRow(i,"cantidadInicial",v)}/></Td><Td><MiniInput type="number" value={x.valorUnitario} onChange={v=>setRow(i,"valorUnitario",v)}/></Td><Td>{x.descripcion?money(num(x.cantidadInicial)*num(x.valorUnitario)):"—"}</Td><Td><MiniInput type="number" value={x.cantidadPresente} onChange={v=>setRow(i,"cantidadPresente",v)}/></Td><Td>{x.descripcion?money(num(x.cantidadPresente)*num(x.valorUnitario)):"—"}</Td><Td><MiniInput type="number" value={x.cantidadAcumulada} onChange={v=>setRow(i,"cantidadAcumulada",v)}/></Td><Td>{x.descripcion?money(num(x.cantidadAcumulada)*num(x.valorUnitario)):"—"}</Td><Td><Remove onClick={()=>set({...d,lineas:d.lineas.filter((_,j)=>j!==i)})}/></Td></tr>)}</tbody></TableWrap><AddRow onClick={()=>set({...d,lineas:[...d.lineas,{id:uid(),codigo:"",descripcion:"",unidad:"UND",cantidadInicial:"",valorUnitario:"",cantidadPresente:"",cantidadAcumulada:""}]})}/><div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-5"><Economic title="Presupuesto inicial" subtotal={t.subtotalInicial} inc={d.incrementoInicial} setInc={v=>set({...d,incrementoInicial:v})} aiu={d.aiuInicial} setAiu={v=>set({...d,aiuInicial:v})} total={t.inicial}/><Economic title="Liquidación presente" subtotal={t.subtotalPresente} inc={d.incrementoPresente} setInc={v=>set({...d,incrementoPresente:v})} aiu={d.aiuPresente} setAiu={v=>set({...d,aiuPresente:v})} total={t.presente}/><Economic title="Liquidación acumulada" subtotal={t.subtotalAcum} inc={d.incrementoAcumulado} setInc={v=>set({...d,incrementoAcumulado:v})} aiu={d.aiuAcumulado} setAiu={v=>set({...d,aiuAcumulado:v})} total={t.acumulado}/></div></Section><Section n="04" title="Valor en letras y firmantes"><Field label="Valor en letras de la presente acta" required textarea value={d.valorLetras} onChange={v=>set({...d,valorLetras:v})}/><div className="mt-4"><Grid><Field label="Representante Electroingeniería S.A.S." value={d.repEi} onChange={v=>set({...d,repEi:v})}/><Field label="Representante Interventoría / Municipio" value={d.repInterventoria} onChange={v=>set({...d,repInterventoria:v})}/></Grid></div></Section></>; }
function Economic({title,subtotal,inc,setInc,aiu,setAiu,total}) { return <div className="border border-[#e5e7eb] rounded-xl p-4"><div className="text-xs font-bold text-azul mb-3">{title}</div><div className="text-xs flex justify-between mb-2"><span className="text-gray-500">Subtotal</span><b>{money(subtotal)}</b></div><label className="text-[11px] text-gray-500">Incremento distancia</label><MiniInput type="number" value={inc} onChange={setInc}/><label className="text-[11px] text-gray-500 block mt-2">AIU %</label><MiniInput type="number" value={aiu} onChange={setAiu}/><div className="flex justify-between mt-3 pt-3 border-t font-bold text-sm"><span>Total</span><span className="text-azul">{money(total)}</span></div></div>; }
function Renderer({tipo,d,set}) { if(tipo==="bitacora")return <Bitacora d={d} set={set}/>; if(tipo==="control-material")return <ControlMaterial d={d} set={set}/>; if(tipo==="solicitud-materiales")return <SolicitudMateriales d={d} set={set}/>; if(tipo==="finalizacion")return <Finalizacion d={d} set={set}/>; if(tipo==="herramienta")return <Herramienta d={d} set={set}/>; if(tipo==="orden")return <Orden d={d} set={set}/>; if(tipo==="liquidacion")return <Liquidacion d={d} set={set}/>; return null; }

export default function ExecutionModule() {
  const [records,setRecords]=useState([]); const [currentId,setCurrentId]=useState(null); const [ready,setReady]=useState(false); const [query,setQuery]=useState("");
  useEffect(()=>{ try{const raw=localStorage.getItem(STORAGE_KEY); if(raw)setRecords(JSON.parse(raw));}catch{} setReady(true); },[]);
  useEffect(()=>{ if(ready)localStorage.setItem(STORAGE_KEY,JSON.stringify(records)); },[records,ready]);
  const current=records.find(r=>r.id===currentId); const formato=current?FORMATOS.find(f=>f.id===current.tipo):null; const alerts=current?validate(current.tipo,current.data):[]; const comp=current?completion(current.tipo,current.data):0;
  const updateData=(data)=>setRecords(rs=>rs.map(r=>r.id===currentId?{...r,data,updatedAt:new Date().toISOString(),status:validate(r.tipo,data).length?"EN DILIGENCIAMIENTO":"LISTO"}:r));
  const create=(tipo)=>{const f=FORMATOS.find(x=>x.id===tipo); const r={id:uid(),tipo,nombre:`${f.nombre} · ${new Date().toLocaleDateString("es-CO")}`,status:"EN DILIGENCIAMIENTO",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),data:defaults(tipo)}; setRecords(rs=>[r,...rs]); setCurrentId(r.id);};
  const remove=(id)=>{if(!confirm("¿Eliminar este registro de Ejecución? Esta acción solo afecta el borrador guardado en este navegador."))return;setRecords(rs=>rs.filter(r=>r.id!==id));if(id===currentId)setCurrentId(null);};
  const shown=records.filter(r=>{const f=FORMATOS.find(x=>x.id===r.tipo); return !query||`${r.nombre} ${f?.nombre}`.toLowerCase().includes(query.toLowerCase());});
  const k={total:records.length,listos:records.filter(r=>r.status==="LISTO").length,revision:records.filter(r=>validate(r.tipo,r.data).length).length};
  if(!ready)return <div className="skeleton h-64 rounded-xl"/>;
  if(current&&formato)return <div className="max-w-[1500px] mx-auto pb-16 print:max-w-none"><div className="no-print flex items-start gap-3 mb-5"><button onClick={()=>setCurrentId(null)} className="mt-1 p-2 rounded-lg bg-white border border-[#d1d5db] text-gray-600 hover:text-azul"><Icon name="back"/></button><div className="flex-1"><div className="flex items-center gap-2 flex-wrap"><Badge tone="blue">{formato.codigo}</Badge><Badge tone={alerts.length?"red":"green"}>{alerts.length?`${alerts.length} por revisar`:"LISTO"}</Badge><span className="text-xs text-gray-400">Autoguardado local · {fechaHora(current.updatedAt)}</span></div><input className="mt-2 w-full bg-transparent text-2xl font-bold text-azul outline-none border-b border-transparent focus:border-azul/20" value={current.nombre} onChange={e=>setRecords(rs=>rs.map(r=>r.id===currentId?{...r,nombre:e.target.value,updatedAt:new Date().toISOString()}:r))}/><p className="text-sm text-gray-500 mt-1">{formato.desc}</p></div><div className="hidden md:flex gap-2"><Boton variant="secondary" onClick={()=>window.print()}><Icon name="print" size={16}/> Imprimir / PDF</Boton></div></div><div className="grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-5"><div><Renderer tipo={current.tipo} d={current.data} set={updateData}/></div><aside className="no-print lg:sticky lg:top-20 self-start"><Card className="p-5 mb-4"><div className="flex items-center justify-between mb-2"><span className="text-xs font-bold text-gray-500 uppercase tracking-wide">Completitud</span><span className="text-sm font-bold text-azul">{pct(comp)}</span></div><div className="h-2.5 bg-gray-100 rounded-full overflow-hidden"><div className="h-full bg-azul rounded-full transition-all" style={{width:pct(comp)}}/></div><p className="text-xs text-gray-400 mt-2">Campos críticos del formato original.</p></Card><Card className="overflow-hidden"><div className="px-4 py-3 bg-azul text-white font-semibold text-sm">Control automático</div><div className="p-4 max-h-[62vh] overflow-y-auto">{alerts.length===0?<div className="text-sm text-[#0f6e56] bg-[#eaf3ee] p-3 rounded-lg">No se detectan pendientes de validación. El registro puede pasar a revisión/firma según el procedimiento interno.</div>:<div className="space-y-2">{alerts.map((x,i)=><div key={i} className="text-xs text-red-700 bg-red-50 border border-red-100 rounded-lg p-2.5">{x}</div>)}</div>}</div></Card><div className="no-print md:hidden mt-4"><Boton variant="secondary" className="w-full" onClick={()=>window.print()}><Icon name="print" size={16}/> Imprimir / PDF</Boton></div></aside></div><style jsx global>{`@media print{.no-print{display:none!important}body{background:white!important}header{display:none!important}main{padding:0!important;background:white!important}}`}</style></div>;
  return <div className="max-w-6xl mx-auto"><div className="mb-7 animate-fade-in"><h1 className="text-2xl font-bold text-azul">Ejecución</h1><p className="text-gray-500 text-sm mt-0.5">Centro operativo de formatos para ejecución, seguimiento y cierre de proyectos.</p></div><div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6"><Stat label="Formatos digitales" value={FORMATOS.length}/><Stat label="Registros locales" value={k.total}/><Stat label="Listos" value={k.listos}/><Stat label="Con revisión" value={k.revision} accent/></div>{["Inicio","Seguimiento","Cierre"].map(etapa=><div key={etapa} className="mb-7"><div className="flex items-center gap-3 mb-3"><h2 className="text-sm font-bold text-[#1a1a1a]">{etapa}</h2><div className="h-px flex-1 bg-[#e5e7eb]"/></div><div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">{FORMATOS.filter(f=>f.etapa===etapa).map(f=><Card key={f.id} className="p-5 card-hover animate-slide-up"><div className="flex items-start gap-4"><div className="h-11 w-11 rounded-xl bg-azul-soft text-azul grid place-items-center shrink-0"><Icon name={f.icon}/></div><div className="flex-1 min-w-0"><div className="flex justify-between gap-2"><div><div className="text-[11px] font-bold text-gray-400">{f.codigo}</div><h3 className="font-bold text-[15px] mt-0.5">{f.nombre}</h3></div><Badge tone="blue">{etapa}</Badge></div><p className="text-xs text-gray-500 mt-2 leading-relaxed min-h-[32px]">{f.desc}</p><Boton size="sm" className="mt-4" onClick={()=>create(f.id)}>+ Nuevo registro</Boton></div></div></Card>)}</div></div>)}<div className="mt-9 mb-4 flex items-end justify-between gap-3 flex-wrap"><div><h2 className="text-lg font-bold text-azul">Mis registros en este navegador</h2><p className="text-xs text-gray-500 mt-0.5">Borradores aislados dentro de Ejecución; no modifican otros módulos ni bases de datos.</p></div><Input className="w-full sm:w-72" placeholder="Buscar registro..." value={query} onChange={e=>setQuery(e.target.value)}/></div>{shown.length===0?<Card className="p-8 text-center text-sm text-gray-400">Aún no hay registros. Selecciona “+ Nuevo registro” en cualquiera de los formatos.</Card>:<div className="space-y-2">{shown.map(r=>{const f=FORMATOS.find(x=>x.id===r.tipo);const al=validate(r.tipo,r.data).length;return <Card key={r.id} className="px-4 py-3 flex items-center gap-3"><div className="h-9 w-9 rounded-lg bg-azul-soft text-azul grid place-items-center"><Icon name={f.icon} size={17}/></div><button className="flex-1 text-left min-w-0" onClick={()=>setCurrentId(r.id)}><div className="font-semibold text-sm truncate">{r.nombre}</div><div className="text-xs text-gray-400">{f.nombre} · actualizado {fechaHora(r.updatedAt)}</div></button><Badge tone={al?"yellow":"green"}>{al?`${al} alertas`:"LISTO"}</Badge><button className="p-2 text-gray-400 hover:text-red-600" onClick={()=>remove(r.id)}><Icon name="trash" size={16}/></button></Card>})}</div>}</div>;
}
